Ltac keeps_callR Sg NEWAP PML K :=
  lazymatch goal with AGx : agree_on (fun a => aclient (rt_live RT ?S5) ?frs ?spx a /\ outside ?W a) ?m1 ?m2 |- _ =>
    assert (K : keeps_live (rt_live RT Sg) m1 m2)
      by (apply (keeps_live_of_agree _ _ _ _ m1 m2 _ AGx);
          [ solve [live_sub_tac]
          | let bb := fresh "bb" in let kk := fresh "kk" in let xx := fresh "xx" in let Hin := fresh "Hin" in let Hxx := fresh "Hxx" in let NX := fresh "NX" in
            intros bb kk xx Hin Hxx; destruct (NEWAP xx (PML bb kk xx Hin Hxx)) as [_ NX]; cbn [outside]; clear - NX; repeat split; try exact I; lia ]) end.

