Ltac livn := repeat match goal with H : rt_live _ _ = rt_live _ _ |- _ => rewrite H end.
Ltac lres_g :=
  unfold lres; repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end;
  repeat match goal with H : rt_live _ ?a = rt_live _ ?b |- _ => rewrite H end;
  cbn [length]; unfold FRAMES_MAX, LIVE_MAX in *;
  split; [repeat match goal with H : context [length (rt_frames _ _)] |- _ => revert H end; clear; intros; lia|];
  split; [repeat match goal with H : context [length (rt_live _ _)] |- _ => revert H end; clear; intros; lia|];
  split; [first [assumption | repeat match goal with H : context [rt_credit _ _] |- _ => revert H end; repeat match goal with H : context [cntp] |- _ => revert H end;
                              clear; intros; unfold HMT_COST, RC1, RASTER_COST in *; unfold cntp in *; lia]|];
  match goal with L : forall p n, In (p, n) (rt_live _ ?S) -> 0 < n |- forall p n, In (p, n) (rt_live _ ?S) -> 0 < n => exact L end.
