Ltac after_call_open2 RT :=
  cps_open RT; after_call_unfold; fold_zdefs; unfold rt_after, rt_after_f in *; split_hyps; unfold SEGTOP_A, STACK_WIN, USTACK_TOP, RT_STACK in *;
  repeat match goal with H : context [bv_unsigned (Z_to_bv 64 ?e)] |- _ => rewrite (unsigned_lit e) in H by lia end;
  lazymatch goal with
  | P : rt_pres ?lv ?frs ?spc ?ma ?mb |- _ =>
      let AG := fresh "AG" in assert (AG : agree_on (aclient lv frs spc) ma mb) by (intros ? Ha; exact (P _ Ha)); clear P
  | P : rt_pres_ex ?lv ?frs ?spc ?d ?n ?ma ?mb |- _ =>
      let AG := fresh "AG" in assert (AG : agree_on (fun a => aclient lv frs spc a /\ ~ (d <= a < d + n)) ma mb) by (intros ? [Ha Hb]; exact (P _ Ha Hb)); clear P
  | P : rt_pres_fp ?lv ?frs ?spc ?W ?ma ?mb |- _ =>
      let AG := fresh "AG" in assert (AG : agree_on (fun a => aclient lv frs spc a /\ outside W a) ma mb) by (intros ? [Ha Hb]; exact (P _ Ha Hb)); clear P
  end.
Ltac tr_cell AG H side :=
  lazymatch type of AG with agree_on _ ?ma ?mb =>
    lazymatch type of H with rw_cells _ _ ?A ?cs =>
      apply (rw_cells_agree_nw asegs ma mb A cs) in H;
      [| let a := fresh "a" in let Ha := fresh "Ha" in intros a Ha; cbn [cells_size csize Nat.add length Z.of_nat Pos.of_succ_nat Pos.succ] in Ha; apply AG; side Ha ] end end.
Ltac drop_old ma := repeat match goal with
  | H : acc asegs ma _ _ |- _ => clear H | H : mem_inv asegs ma |- _ => clear H | H : stk asegs ma _ _ |- _ => clear H
  | H : munch _ _ ma |- _ => clear H | H : wmono asegs _ ma |- _ => clear H | H : wr_at asegs ma _ _ |- _ => clear H
  | H : rw_cells asegs ma _ _ |- _ => fail 100 "leftover cell (add a tr_cell case):" H | H : ro_cells asegs ma _ _ |- _ => clear H | H : bytes_at asegs ma _ _ |- _ => clear H
  | H : LIBH ma |- _ => clear H | H : io_ssp ma |- _ => clear H end.
