                                          | cbn [outside]; clear - Ha; lia ]) end;
    repeat match goal with H : rw_cells asegs ma fr _ |- _ =>
      tr_cell AG H ltac:(fun Ha => split; [ right; right; right; left; exists fr, 2%nat; split; [rewrite FRSx; left; reflexivity| change (fs_size 2%nat) with 256; clear - Ha; lia]
                                          | cbn [outside]; clear - Ha; lia ]) end;
    repeat match goal with H : rw_cells asegs ma (fr / 8 + _) _ |- _ =>
      tr_cell AG H ltac:(fun Ha => split; [ right; right; right; right; exists fr, 2%nat; split; [rewrite FRSx; left; reflexivity| unfold shad, SHB; change (fs_size 2%nat) with 256; clear - Ha FR64; Z.div_mod_to_equations; lia]
                                          | cbn [outside]; clear - Ha FRSH FR0; unfold parked in *; lia ]) end;
    repeat match goal with H : rw_cells asegs ma (usp + ?o) _ |- _ =>
      tr_cell AG H ltac:(fun Ha => split; [ left; unfold USTACK_TOP; clear - Ha SPT; lia | cbn [outside]; clear - Ha FRHI LOW LOR; unfold parked in *; lia ]) end
  end.
